#!/usr/bin/env python3\n"""Move the original starter bank into the Very Easy foundation tier."""\nfrom pathlib import Path\nimport json\n\nROOT = Path(__file__).resolve().parents[1]\ncount = 0\nfor path in sorted((ROOT / "data" / "questions").rglob("*.json")):\n    records = json.loads(path.read_text(encoding="utf-8"))\n    changed = False\n    for q in records:\n        if q.get("content_type") == "original_exam_style" and q.get("source_reference") == "stage-1-original-bank":\n            if q.get("difficulty") != "Very Easy":\n                q["difficulty"] = "Very Easy"\n                changed = True\n                count += 1\n    if changed:\n        path.write_text(json.dumps(records, indent=2, ensure_ascii=False) + "\\n", encoding="utf-8")\nprint(f"Moved {count} starter questions to Very Easy.")\n